CREATE TABLE password_folder (id UUID PRIMARY KEY DEFAULT uuid_v7(),vault_id UUID NOT NULL,owner_id UUID NOT NULL,parent_id UUID,encrypted_name TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),version BIGINT NOT NULL DEFAULT 0,FOREIGN KEY(vault_id) REFERENCES password_vault(id),FOREIGN KEY(parent_id) REFERENCES password_folder(id)); CREATE TABLE password_item_folder (id UUID PRIMARY KEY DEFAULT uuid_v7(),item_id UUID NOT NULL UNIQUE,folder_id UUID NOT NULL,vault_id UUID NOT NULL,owner_id UUID NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),FOREIGN KEY(item_id) REFERENCES password_vault_item(id),FOREIGN KEY(folder_id) REFERENCES password_folder(id),FOREIGN KEY(vault_id) REFERENCES password_vault(id));
